-- 01-osint-corporate.json
insert into public.training_scenarios (slug, sort_order, title, description, difficulty, category, estimated_minutes, skills, content, grading_rubric)
values ('osint-corporate-investigation', 1, 'OSINT Corporate Investigation — Velora Componenti S.p.A.', 'Analisi di una società completamente fittizia: verifica delle fonti, ricostruzione cronologica e individuazione delle incongruenze.', 'beginner', 'corporate_due_diligence',
        60, array['Valutazione delle fonti', 'Scala Admiralty', 'Cronologia', 'Gestione delle incongruenze', 'Reporting']::text[], '{"scenario":"Il cliente (un''azienda manifatturiera fittizia) sta per firmare un contratto di fornitura triennale con Velora Componenti S.p.A. e chiede una verifica di due diligence leggera basata esclusivamente su fonti aperte. Tutti i soggetti, i luoghi e i documenti sono inventati.","briefing":{"from":"Responsabile Intelligence (fittizio)","text":"Ci servono entro oggi le prime evidenze su Velora Componenti. Non contattare la società e non creare account falsi: lavora solo sui documenti allegati, che simulano quanto raccolto da fonti aperte. Distingui sempre ciò che è verificato da ciò che è solo dichiarato."},"objective":"Valutare la coerenza delle informazioni pubbliche su Velora Componenti S.p.A., ricostruire una cronologia affidabile e segnalare le incongruenze rilevanti per il cliente.","documents":[{"id":"doc-registry","title":"Estratto registro imprese (fittizio)","kind":"text","source":"Registro imprese — fonte primaria (simulata)","body":"Denominazione: VELORA COMPONENTI S.P.A.\nSede legale: Via Industria 22, Brescia (BS)\nData costituzione: 15/03/2017\nCapitale sociale: 120.000 EUR\nAmministratore delegato: Giulia Ferri (fittizia)\nAttività: produzione di componenti meccanici di precisione\nUnità locali: nessuna registrata"},{"id":"doc-website","title":"Pagina \"Chi siamo\" del sito aziendale (fittizio)","kind":"text","source":"Sito istituzionale velora-componenti.example","body":"Dal 2009 Velora Componenti è sinonimo di eccellenza. La nostra sede di Milano coordina oltre 250 dipendenti. Siamo certificati ISO 27001 per la sicurezza delle informazioni. Il nostro CEO, Marco Valli, guida l''azienda dalla fondazione."},{"id":"doc-press","title":"Comunicato stampa (fittizio)","kind":"text","source":"Portale comunicati stampa (simulato)","body":"12/06/2016 — Velora Componenti inaugura il nuovo stabilimento di Brescia alla presenza dell''amministratore delegato Giulia Ferri."},{"id":"doc-cert","title":"Consultazione registro certificazioni (fittizio)","kind":"text","source":"Registro pubblico degli organismi di certificazione (simulato)","body":"Ricerca: Velora Componenti S.p.A.\nCertificato ISO/IEC 27001 n. IT-55821 — stato: REVOCATO in data 02/05/2023.\nNessun certificato attivo."},{"id":"doc-news","title":"Articolo di stampa locale (fittizio)","kind":"text","source":"Testata locale online (simulata), articolo non firmato","body":"Velora Componenti, azienda bresciana con circa 60 dipendenti, ha annunciato un piano di espansione. Secondo fonti non ufficiali, la società starebbe valutando l''apertura di un ufficio commerciale a Milano."}],"tasks":["Classifica ogni documento per affidabilità della fonte (scala Admiralty A–F).","Ricostruisci la cronologia degli eventi indicando data dell''evento e fonte.","Individua le incongruenze tra le fonti.","Etichetta ogni informazione chiave come fatto verificato, da verificare, ipotesi o contraddittoria.","Redigi una breve nota per il cliente con conclusioni e raccomandazioni."],"tools":["OSINT Workspace","Investigation Timeline (dettaglio caso)","Report Generator"],"instructions":["Lavora solo sui documenti forniti: non effettuare ricerche su persone reali.","Una fonte primaria (es. registro ufficiale) prevale su dichiarazioni autoriferite (es. sito aziendale).","Un''informazione smentita da un''altra fonte è contraddittoria, non automaticamente falsa: spiega perché.","Indica i limiti della tua analisi."],"deliverable":{"title":"Nota di due diligence (max 1 pagina)","sections":["Sintesi","Fonti consultate e affidabilità","Cronologia","Incongruenze","Conclusioni e raccomandazioni","Limitazioni"]},"questions":[{"id":"q1","type":"single","prompt":"Quale documento è la fonte più affidabile per sede legale e data di costituzione?","options":[{"value":"a","label":"La pagina \"Chi siamo\" del sito aziendale"},{"value":"b","label":"L''estratto del registro imprese"},{"value":"c","label":"L''articolo di stampa locale"},{"value":"d","label":"Il comunicato stampa"}]},{"id":"q2","type":"multi","prompt":"Quali incongruenze emergono dai documenti? (seleziona tutte quelle corrette)","options":[{"value":"a","label":"Anno di fondazione: 2009 sul sito, 2017 nel registro"},{"value":"b","label":"Sede: Milano sul sito, Brescia nel registro"},{"value":"c","label":"CEO: Marco Valli sul sito, Giulia Ferri nel registro e nel comunicato"},{"value":"d","label":"Certificazione ISO 27001 dichiarata ma risultante revocata"},{"value":"e","label":"Capitale sociale diverso tra registro e articolo"},{"value":"f","label":"Comunicato stampa datato prima della costituzione della società"}]},{"id":"q3","type":"single","prompt":"Come etichetti l''affermazione \"Siamo certificati ISO 27001\"?","options":[{"value":"verified_fact","label":"Fatto verificato"},{"value":"to_verify","label":"Informazione da verificare"},{"value":"hypothesis","label":"Ipotesi analitica"},{"value":"contradictory","label":"Informazione contraddittoria"}]},{"id":"q4","type":"single","prompt":"Quale affidabilità (scala Admiralty) assegni all''articolo di stampa locale non firmato che cita \"fonti non ufficiali\"?","options":[{"value":"A","label":"A — completamente affidabile"},{"value":"B","label":"B — generalmente affidabile"},{"value":"C","label":"C — abbastanza affidabile"},{"value":"E","label":"E — inaffidabile"}]},{"id":"q5","type":"keywords","prompt":"Spiega in poche righe come gestiresti l''incongruenza sull''anno di fondazione e quale verifica proporresti.","placeholder":"Es. quale fonte prevale, quale dato riporteresti, quale verifica aggiuntiva..."}]}'::jsonb, '[{"id":"sources","criterion":"Valutazione delle fonti","description":"Ogni fonte ha un livello di affidabilità motivato; la fonte primaria è riconosciuta come tale.","weight":25},{"id":"timeline","criterion":"Cronologia","description":"Eventi ordinati con data e fonte; distinzione tra data dell''evento e data di acquisizione.","weight":20},{"id":"inconsistencies","criterion":"Incongruenze","description":"Le incongruenze sono individuate e spiegate senza trarre conclusioni non supportate.","weight":25},{"id":"labels","criterion":"Fatti vs ipotesi","description":"Fatti, ipotesi e informazioni contraddittorie sono etichettati correttamente.","weight":15},{"id":"report","criterion":"Qualità della nota","description":"Struttura chiara, conclusioni proporzionate, raccomandazioni operative e limiti dichiarati.","weight":15}]'::jsonb)
on conflict (slug) do update set
  sort_order = excluded.sort_order, title = excluded.title, description = excluded.description,
  difficulty = excluded.difficulty, category = excluded.category, estimated_minutes = excluded.estimated_minutes,
  skills = excluded.skills, content = excluded.content, grading_rubric = excluded.grading_rubric;

insert into public.training_answer_keys (scenario_id, answer_key, solution)
select id, '{"q1":{"type":"single","correct":"b","points":2,"explanation":"Il registro imprese è una fonte primaria e ufficiale; sito e comunicati sono dichiarazioni dell''interessato o di terzi."},"q2":{"type":"multi","correct":["a","b","c","d","f"],"points":3,"explanation":"Il capitale sociale non è citato dall''articolo (opzione e errata). Il comunicato del 12/06/2016 precede la costituzione del 15/03/2017: è un''ulteriore incongruenza da approfondire."},"q3":{"type":"single","correct":"contradictory","points":2,"explanation":"L''affermazione è smentita dal registro certificazioni (certificato revocato): è un''informazione contraddittoria, da segnalare al cliente."},"q4":{"type":"single","correct":"C","points":1,"explanation":"Una testata identificabile ma con articolo non firmato e fonti anonime è al massimo ''abbastanza affidabile''; le singole affermazioni restano da verificare."},"q5":{"type":"keywords","keywords":[["registro","visura","fonte primaria"],["2017"],["2009","sito"],["verific","richiest","conferm","approfond"]],"points":2,"explanation":"Riporta il 2017 (fonte primaria), segnala il 2009 come dichiarazione non supportata (forse riferita a un''attività precedente o a un''altra entità) e proponi una verifica: es. richiesta documentale o ricerca di eventuali società predecessori."}}'::jsonb, '{"summary":"Velora Componenti S.p.A. esiste ed è registrata a Brescia dal 15/03/2017 con AD Giulia Ferri. Il sito aziendale contiene affermazioni non coerenti con le fonti primarie (anno di fondazione, sede, CEO, numero di dipendenti, certificazione ISO 27001 revocata). Il comunicato del 2016 precede la costituzione.","key_findings":["Fatto verificato: costituzione 15/03/2017, sede legale Brescia, AD Giulia Ferri (registro, affidabilità A).","Contraddittorio: certificazione ISO 27001 dichiarata sul sito ma revocata il 02/05/2023.","Contraddittorio: CEO indicato come Marco Valli sul sito.","Da verificare: ufficio di Milano (articolo non firmato, fonti anonime, affidabilità C).","Ipotesi: il 2009 potrebbe riferirsi a una società predecessore; va verificato prima di affermarlo."],"timeline":["2009 — fondazione dichiarata dal sito (non supportata da fonti primarie)","12/06/2016 — comunicato inaugurazione stabilimento (anteriore alla costituzione: anomalia)","15/03/2017 — costituzione (registro, fatto verificato)","02/05/2023 — revoca certificato ISO 27001 (registro certificazioni)"],"common_mistakes":["Considerare il sito aziendale come fonte verificata.","Concludere che la società è fraudolenta: i dati giustificano cautela e ulteriori verifiche, non un giudizio definitivo.","Non distinguere la data dell''evento dalla data in cui l''analista l''ha appresa."],"recommendations":["Chiedere al fornitore visura aggiornata, certificazioni in corso di validità e chiarimenti sul CEO indicato sul sito.","Subordinare la firma alla verifica dei requisiti di sicurezza dichiarati (ISO 27001 non attiva)."]}'::jsonb from public.training_scenarios where slug = 'osint-corporate-investigation'
on conflict (scenario_id) do update set answer_key = excluded.answer_key, solution = excluded.solution;

-- 02-suspicious-domain.json
insert into public.training_scenarios (slug, sort_order, title, description, difficulty, category, estimated_minutes, skills, content, grading_rubric)
values ('suspicious-domain-investigation', 2, 'Suspicious Domain Investigation — velora-componenti-supporto.example', 'Lettura di record DNS, dati RDAP e Certificate Transparency forniti per valutare un possibile dominio di impersonificazione.', 'beginner', 'domain_investigation',
        45, array['DNS', 'RDAP', 'SPF/DMARC', 'Certificate Transparency', 'Valutazione del rischio motivata']::text[], '{"scenario":"Il team di sicurezza di Velora Componenti (fittizia) ha ricevuto da un cliente la segnalazione di email provenienti da velora-componenti-supporto.example. Il dominio legittimo è velora-componenti.example. Tutti i dati sono simulati e usano domini e indirizzi riservati alla documentazione.","briefing":{"from":"SOC Manager (fittizio)","text":"Valuta se il dominio è legato a un tentativo di impersonificazione. Non visitare il sito e non interagire con l''infrastruttura: usa solo i dati passivi già raccolti qui sotto."},"objective":"Interpretare i dati tecnici del dominio, identificare le anomalie e produrre una valutazione del rischio motivata.","documents":[{"id":"doc-dns","title":"Record DNS (raccolti passivamente, simulati)","kind":"dns","source":"Resolver DNS (simulato)","body":"velora-componenti-supporto.example.  A     203.0.113.66\nvelora-componenti-supporto.example.  NS    ns1.hostveloce.example.\nvelora-componenti-supporto.example.  NS    ns2.hostveloce.example.\nvelora-componenti-supporto.example.  MX    10 mail.hostveloce.example.\nvelora-componenti-supporto.example.  TXT   \"v=spf1 +all\"\n_dmarc.velora-componenti-supporto.example.  (nessun record)"},{"id":"doc-legit-dns","title":"Record DNS del dominio legittimo (riferimento)","kind":"dns","source":"Resolver DNS (simulato)","body":"velora-componenti.example.  A     198.51.100.10\nvelora-componenti.example.  MX    10 mx1.velora-componenti.example.\nvelora-componenti.example.  TXT   \"v=spf1 ip4:198.51.100.0/28 -all\"\n_dmarc.velora-componenti.example.  TXT \"v=DMARC1; p=reject; rua=mailto:dmarc@velora-componenti.example\""},{"id":"doc-rdap","title":"Risposta RDAP (simulata)","kind":"text","source":"RDAP del registro (simulato)","body":"Dominio: velora-componenti-supporto.example\nRegistrar: Registrar Economico Ltd (fittizio)\nRegistrazione: 6 giorni fa\nScadenza: tra 1 anno\nRegistrante: REDACTED FOR PRIVACY\nStato: clientTransferProhibited"},{"id":"doc-ct","title":"Certificate Transparency (simulato)","kind":"text","source":"Log CT (simulato)","body":"Certificato DV emesso 6 giorni fa (stesso giorno della registrazione).\nSAN: velora-componenti-supporto.example, login.velora-componenti-supporto.example, fatture.velora-componenti-supporto.example"}],"tasks":["Confronta la configurazione DNS del dominio sospetto con quella del dominio legittimo.","Interpreta i record SPF e DMARC.","Interpreta i dati RDAP e CT (date, registrante, sottodomini).","Elenca le anomalie individuate.","Assegna un livello di rischio motivato e proponi azioni."],"tools":["Domain Analysis","OSINT Workspace","Report Generator"],"instructions":["Non visitare il dominio e non effettuare scansioni: i dati passivi sono sufficienti.","L''oscuramento dei dati del registrante è comune (GDPR) e da solo non è indice di malevolenza.","Motiva il livello di rischio con elementi concreti; il punteggio non sostituisce il giudizio professionale."],"deliverable":{"title":"Domain Investigation Note","sections":["Dominio analizzato","Dati raccolti","Anomalie","Valutazione del rischio","Azioni raccomandate","Limitazioni"]},"questions":[{"id":"q1","type":"single","prompt":"Cosa significa il record SPF \"v=spf1 +all\"?","options":[{"value":"a","label":"Solo i server elencati possono inviare posta"},{"value":"b","label":"Qualsiasi server è autorizzato a inviare posta per il dominio"},{"value":"c","label":"Il dominio non invia posta"},{"value":"d","label":"La posta non autenticata viene rifiutata"}]},{"id":"q2","type":"multi","prompt":"Quali elementi costituiscono anomalie rilevanti? (seleziona tutte quelle corrette)","options":[{"value":"a","label":"Dominio registrato da pochi giorni"},{"value":"b","label":"SPF permissivo (+all)"},{"value":"c","label":"Assenza di record DMARC"},{"value":"d","label":"Sottodomini \"login\" e \"fatture\" nel certificato"},{"value":"e","label":"Il dominio ha una data di scadenza"},{"value":"f","label":"Nome che combina il brand con il termine \"supporto\""}]},{"id":"q3","type":"single","prompt":"Il registrante è \"REDACTED FOR PRIVACY\". Come lo interpreti?","options":[{"value":"a","label":"Prova certa di attività malevola"},{"value":"b","label":"Elemento neutro, comune per effetto del GDPR: non è indicativo da solo"},{"value":"c","label":"Indica che il dominio è legittimo"},{"value":"d","label":"Indica che il dominio è scaduto"}]},{"id":"q4","type":"single","prompt":"Quale passo successivo è appropriato?","options":[{"value":"a","label":"Visitare il sito dal proprio PC aziendale per vedere il contenuto"},{"value":"b","label":"Effettuare una scansione delle porte del server"},{"value":"c","label":"Documentare gli indicatori, bloccarli sui sistemi di posta/proxy e valutare una segnalazione di abuso al registrar"},{"value":"d","label":"Contattare il registrante via email"}]},{"id":"q5","type":"keywords","prompt":"Motiva in poche righe il livello di rischio che assegni.","placeholder":"Cita gli elementi tecnici che supportano la tua valutazione..."}]}'::jsonb, '[{"id":"dns","criterion":"Lettura dei record DNS","description":"Record A, NS, MX, TXT interpretati correttamente e confrontati con il dominio legittimo.","weight":25},{"id":"auth","criterion":"SPF / DMARC","description":"Spiega il significato di +all e l''assenza di DMARC.","weight":20},{"id":"context","criterion":"RDAP e CT","description":"Usa date di registrazione/emissione e sottodomini come indicatori; non sovrastima l''oscuramento del registrante.","weight":20},{"id":"risk","criterion":"Valutazione motivata","description":"Il livello di rischio è sostenuto da elementi concreti e accompagnato dai limiti dell''analisi.","weight":25},{"id":"ethics","criterion":"Metodo non intrusivo","description":"Nessuna interazione attiva con l''infrastruttura sospetta.","weight":10}]'::jsonb)
on conflict (slug) do update set
  sort_order = excluded.sort_order, title = excluded.title, description = excluded.description,
  difficulty = excluded.difficulty, category = excluded.category, estimated_minutes = excluded.estimated_minutes,
  skills = excluded.skills, content = excluded.content, grading_rubric = excluded.grading_rubric;

insert into public.training_answer_keys (scenario_id, answer_key, solution)
select id, '{"q1":{"type":"single","correct":"b","points":2,"explanation":"Il qualificatore \"+\" su \"all\" autorizza qualsiasi host: l''SPF non offre alcuna protezione ed è tipico di domini creati per inviare posta fraudolenta."},"q2":{"type":"multi","correct":["a","b","c","d","f"],"points":3,"explanation":"Avere una scadenza è normale per ogni dominio (opzione e errata)."},"q3":{"type":"single","correct":"b","points":1,"explanation":"La redazione dei dati è standard dopo il GDPR: non è un indicatore di malevolenza se isolata."},"q4":{"type":"single","correct":"c","points":2,"explanation":"Visite dirette e scansioni sono interazioni attive con infrastruttura potenzialmente ostile e possono essere non autorizzate. Documentazione, blocco e segnalazione sono azioni difensive appropriate."},"q5":{"type":"keywords","keywords":[["registr","recente","giorni"],["spf","+all"],["dmarc"],["brand","sosia","typosquat","impersonific","somiglian"]],"points":2,"explanation":"Una motivazione solida combina età del dominio, configurazione email permissiva, assenza di DMARC e somiglianza con il brand."}}'::jsonb, '{"summary":"Rischio alto: dominio registrato 6 giorni fa che imita il brand, con SPF +all, senza DMARC e con certificato per sottodomini \"login\" e \"fatture\": profilo coerente con un''infrastruttura predisposta per phishing o frodi sui pagamenti.","key_findings":["Età del dominio: 6 giorni; certificato emesso lo stesso giorno.","SPF +all: chiunque può inviare email a nome del dominio.","DMARC assente, a differenza del dominio legittimo (p=reject).","Sottodomini login./fatture. suggeriscono pagine di raccolta credenziali o pagamenti.","Registrante oscurato: elemento neutro."],"recommendations":["Bloccare dominio e sottodomini su gateway email e proxy web.","Avvisare clienti e fornitori del tentativo di impersonificazione.","Valutare segnalazione di abuso al registrar e all''hosting provider.","Monitorare nuovi certificati che contengono il nome del brand."],"common_mistakes":["Visitare il dominio per \"vedere com''è\".","Considerare il registrante oscurato come prova di malevolenza.","Assegnare il rischio senza motivazione."]}'::jsonb from public.training_scenarios where slug = 'suspicious-domain-investigation'
on conflict (scenario_id) do update set answer_key = excluded.answer_key, solution = excluded.solution;

-- 03-phishing-email.json
insert into public.training_scenarios (slug, sort_order, title, description, difficulty, category, estimated_minutes, skills, content, grading_rubric)
values ('phishing-email-investigation', 3, 'Phishing Email Investigation — falso corriere SpediRapido', 'Analisi degli header e del contenuto di un''email fittizia di falso corriere: autenticazione, indicatori sospetti, evidenze e rapporto.', 'beginner', 'phishing_investigation',
        45, array['Header email', 'SPF/DKIM/DMARC', 'Estrazione IOC', 'Gestione allegati sospetti', 'Reporting']::text[], '{"scenario":"Un dipendente dell''organizzazione simulata ha segnalato un''email che chiede il pagamento di 1,99 EUR per sbloccare una spedizione. Il messaggio è fittizio e sanitizzato: domini .example, indirizzi IP di documentazione.","briefing":{"from":"Responsabile SOC (fittizio)","text":"Analizza il messaggio, decidi se è phishing e prepara un breve rapporto con gli indicatori da bloccare. Non aprire allegati e non cliccare link: i link sono riportati come testo inattivo."},"objective":"Determinare la natura del messaggio sulla base di evidenze tecniche e di contenuto, estrarre gli indicatori e documentare la valutazione.","sample_key":"fake-courier","documents":[{"id":"doc-eml","title":"Messaggio segnalato (header e corpo, sanitizzato)","kind":"email","source":"Segnalazione interna (simulata)","body":"Received: from mail.spedirapido-tracking.example (unknown [198.51.100.77])\n\tby mx.organizzazione.example with ESMTP id 4F2A1; Tue, 17 Nov 2026 08:14:03 +0100\nAuthentication-Results: mx.organizzazione.example;\n\tspf=softfail (domain of transitioning bounce@bulkmail-sender.example does not designate 198.51.100.77 as permitted sender) smtp.mailfrom=bounce@bulkmail-sender.example;\n\tdkim=fail header.d=bulkmail-sender.example;\n\tdmarc=fail (p=none) header.from=spedirapido.example\nFrom: \"SpediRapido Notifiche\" <notifiche@spedirapido.example>\nReply-To: assistenza@spedirapido-supporto.example\nReturn-Path: <bounce@bulkmail-sender.example>\nTo: dipendente@organizzazione.example\nSubject: Il tuo pacco è in giacenza - azione richiesta entro 24 ore\nDate: Tue, 17 Nov 2026 08:13:58 +0100\nMessage-ID: <8812.ab@bulkmail-sender.example>\nContent-Type: multipart/mixed\n\nGentile cliente,\nil tuo pacco non può essere consegnato per mancato pagamento delle spese di sdoganamento (1,99 EUR).\nPaga ora entro 24 ore per evitare la restituzione al mittente:\n<a href=\"http://spedirapido.tracking-update.example/pay?id=7781\">https://www.spedirapido.example/traccia</a>\n\nAllegato: Ricevuta_Spedizione.pdf.html"}],"tasks":["Esamina gli header: mittente, Reply-To, Return-Path, Received.","Interpreta i risultati SPF, DKIM e DMARC.","Estrai URL e domini come testo inattivo.","Valuta l''allegato senza aprirlo.","Formula un verdetto motivato e un rapporto con gli indicatori."],"tools":["Phishing Lab","Threat Intelligence (registro IOC)","Report Generator"],"instructions":["Puoi caricare lo stesso messaggio nel Phishing Lab con il campione \"Falso corriere\" per l''analisi automatica degli header.","L''analisi automatica è un supporto: il verdetto finale è dell''analista.","Riporta gli URL in forma defanged (hxxp, [.])."],"deliverable":{"title":"Phishing Investigation Report","sections":["Sintesi e verdetto","Header e autenticazione","Indicatori estratti","Allegato","Azioni raccomandate","Limitazioni"]},"questions":[{"id":"q1","type":"multi","prompt":"Quali risultati di autenticazione sono negativi? (seleziona tutti quelli corretti)","options":[{"value":"spf","label":"SPF (softfail)"},{"value":"dkim","label":"DKIM (fail)"},{"value":"dmarc","label":"DMARC (fail)"},{"value":"tls","label":"TLS (fail)"}]},{"id":"q2","type":"single","prompt":"Quale elemento identifica in modo più affidabile il server che ha consegnato il messaggio?","options":[{"value":"a","label":"L''indirizzo nel campo From"},{"value":"b","label":"L''header Received aggiunto dal nostro server MX, che registra l''IP che si è connesso"},{"value":"c","label":"Il Message-ID"},{"value":"d","label":"Il nome visualizzato del mittente"}]},{"id":"q3","type":"single","prompt":"Il testo del link mostra www.spedirapido.example ma la destinazione reale è diversa. Qual è la destinazione reale?","options":[{"value":"a","label":"www.spedirapido.example"},{"value":"b","label":"spedirapido.tracking-update.example"},{"value":"c","label":"bulkmail-sender.example"},{"value":"d","label":"organizzazione.example"}]},{"id":"q4","type":"single","prompt":"Come gestisci l''allegato \"Ricevuta_Spedizione.pdf.html\"?","options":[{"value":"a","label":"Lo apro per verificare se è davvero una ricevuta"},{"value":"b","label":"Non lo apro: doppia estensione, file HTML che può contenere un form di phishing; ne documento nome e hash e, se previsto dalle procedure, lo analizzo in ambiente isolato"},{"value":"c","label":"Lo inoltro ai colleghi per un parere"},{"value":"d","label":"Lo rinomino in .pdf e lo apro"}]},{"id":"q5","type":"keywords","prompt":"Scrivi la sintesi del verdetto (3–5 righe) citando le evidenze principali.","placeholder":"Verdetto, evidenze tecniche, evidenze di contenuto..."}]}'::jsonb, '[{"id":"headers","criterion":"Analisi header","description":"From, Reply-To, Return-Path e Received interpretati correttamente.","weight":25},{"id":"auth","criterion":"Autenticazione","description":"SPF, DKIM e DMARC interpretati e collegati al dominio del mittente.","weight":20},{"id":"ioc","criterion":"Indicatori","description":"URL, domini e IP estratti in forma defanged e distinguendo indicatori certi da contesto.","weight":20},{"id":"safety","criterion":"Gestione sicura","description":"Nessuna interazione con link o allegati; procedure di analisi sicura citate.","weight":15},{"id":"report","criterion":"Verdetto e rapporto","description":"Verdetto motivato, livello di confidenza, azioni e limiti.","weight":20}]'::jsonb)
on conflict (slug) do update set
  sort_order = excluded.sort_order, title = excluded.title, description = excluded.description,
  difficulty = excluded.difficulty, category = excluded.category, estimated_minutes = excluded.estimated_minutes,
  skills = excluded.skills, content = excluded.content, grading_rubric = excluded.grading_rubric;

insert into public.training_answer_keys (scenario_id, answer_key, solution)
select id, '{"q1":{"type":"multi","correct":["spf","dkim","dmarc"],"points":3,"explanation":"SPF softfail, DKIM fail (firma di un dominio terzo) e DMARC fail sul dominio dichiarato nel From. Non c''è alcun risultato TLS nell''header."},"q2":{"type":"single","correct":"b","points":2,"explanation":"Gli header aggiunti dai propri server sono gli unici affidabili; From, nome visualizzato e Message-ID sono controllati dal mittente."},"q3":{"type":"single","correct":"b","points":2,"explanation":"Il testo visibile di un link non coincide necessariamente con l''href: la destinazione è spedirapido.tracking-update.example (dominio registrabile: tracking-update.example)."},"q4":{"type":"single","correct":"b","points":2,"explanation":"La doppia estensione .pdf.html è una tecnica comune per far aprire pagine HTML di phishing in locale."},"q5":{"type":"keywords","keywords":[["phishing","malevol","fraudolent"],["spf","dkim","dmarc","autenticazion"],["reply-to","return-path","mittente"],["link","url","dominio"],["urgen","24 ore","pagamento"]],"points":3,"explanation":"Un buon verdetto combina evidenze di autenticazione, incoerenze degli header, link ingannevole, leva dell''urgenza e richiesta di pagamento."}}'::jsonb, '{"summary":"Phishing (confidenza alta). Il messaggio impersona il corriere SpediRapido: autenticazione fallita (SPF softfail, DKIM fail, DMARC fail), Reply-To e Return-Path su domini diversi dal mittente, link ingannevole verso tracking-update.example, urgenza (24 ore), micro-pagamento e allegato HTML con doppia estensione.","indicators":["IP: 198.51.100.77","Dominio: spedirapido.tracking-update.example (registrabile: tracking-update.example)","URL: hxxp://spedirapido.tracking-update[.]example/pay?id=7781","Dominio Reply-To: spedirapido-supporto.example","Dominio Return-Path: bulkmail-sender.example","Allegato: Ricevuta_Spedizione.pdf.html"],"recommendations":["Bloccare domini e URL su gateway email e proxy.","Cercare messaggi analoghi nelle caselle aziendali e rimuoverli.","Avvisare il personale con una comunicazione di sensibilizzazione.","Verificare se qualche utente ha cliccato o inserito dati di pagamento."],"common_mistakes":["Fidarsi del nome visualizzato del mittente.","Leggere solo il testo del link e non la destinazione reale.","Aprire l''allegato per curiosità."]}'::jsonb from public.training_scenarios where slug = 'phishing-email-investigation'
on conflict (scenario_id) do update set answer_key = excluded.answer_key, solution = excluded.solution;
